fn fixture()->SemioBrepSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let a=SemioPoint3{x:1.0,y:2.0,z:3.0};let b=SemioPoint3{x:0.0,y:0.0,z:1.0};let u=SemioPoint2{x:1.0,y:2.0};let v=SemioPoint2{x:3.0,y:4.0};let curves=vec![BrepCurve::Line{origin:a,direction:b},BrepCurve::Circle{center:a,axis:b,radius:2.5},BrepCurve::Ellipse{center:a,axis:b,radius_major:3.5,radius_minor:1.25},BrepCurve::Nurbs{control_points:vec![a,b],weights:vec![1.0,0.5],degree:1,knots:vec![0.0,0.0,1.0,1.0]}];let pcurves=vec![BrepCurve2::Line{origin:u,direction:v},BrepCurve2::Circle{center:u,radius:2.5},BrepCurve2::Ellipse{center:u,x_axis:v,radius_major:3.5,radius_minor:1.25},BrepCurve2::Nurbs{control_points:vec![u,v],weights:vec![1.0,0.5],degree:1,knots:vec![0.0,0.0,1.0,1.0]}];let surfaces=vec![BrepSurface::Plane{origin:a,normal:b},BrepSurface::Cylinder{origin:a,axis:b,radius:2.5},BrepSurface::Cone{origin:a,axis:b,radius:2.5,half_angle:0.25},BrepSurface::Sphere{center:a,radius:2.5},BrepSurface::Torus{center:a,axis:b,major_radius:3.5,minor_radius:1.25},BrepSurface::Nurbs{control_points:vec![a,b],weights:vec![1.0,0.5],u_count:1,v_count:2,degree_u:0,degree_v:1,knots_u:vec![0.0,1.0],knots_v:vec![0.0,0.0,1.0,1.0]}];SemioBrepSnapshot{schema:f["schema"].as_str().unwrap().into(),vertices:vec![BrepVertex{id:"v0".into(),point:a,tol:0.001},BrepVertex{id:"v-文".into(),point:b,tol:0.002}],edges:curves.into_iter().enumerate().map(|(i,curve)|BrepEdge{id:format!("e{i}"),start_vertex:"v0".into(),end_vertex:"v-文".into(),curve,tol:0.003}).collect(),loops:vec![BrepLoop{id:"loop".into(),edges:(0..4).map(|i|BrepLoopEdge{edge:format!("e{i}"),orientation:i%2==0}).collect()},BrepLoop{id:"inner".into(),edges:vec![]}],faces:surfaces.into_iter().enumerate().map(|(i,surface)|BrepFace{id:format!("f{i}"),outer_loop:"loop".into(),inner_loops:vec!["inner".into()],surface,orientation:i%2==0,tol:0.004}).collect(),shells:vec![BrepShell{id:"shell".into(),faces:(0..6).map(|i|BrepShellFace{face:format!("f{i}"),orientation:i%2==0}).collect()}],solids:vec![BrepSolid{id:"solid".into(),shells:vec![BrepSolidShell{shell:"shell".into(),is_void:false},BrepSolidShell{shell:"shell".into(),is_void:true}]}],coedges:pcurves.into_iter().enumerate().map(|(i,pcurve)|BrepCoedge{id:format!("c{i}"),edge:format!("e{i}"),forward:i%2==0,pcurve:Some(pcurve),prange:(-1.0,2.0),loop_id:"loop".into(),next:format!("c{}",(i+1)%4),prev:format!("c{}",(i+3)%4)}).collect(),next_label:f["nextLabel"].as_str().unwrap().parse().unwrap()}}
