fn restore(db:&SqliteDatabase)->Result<SemioBrepSnapshot, semio_framework_value::ValueError>{SemioBrepSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
