test("Semio BRep shared native-admission frontier has independent scalar rows and interior controls",async()=>{const a=f.nativeAdmission,s:SemioBrepSnapshot={schema:f.schema,nextLabel:BigInt(f.nextLabel),vertices:Array.from({length:a.collectionItems},(_,i)=>({id:i.toString(),point:{x:{bits:BigInt("0x"+f.float64Bits[i%f.float64Bits.length])},y:binary64(0),z:binary64(0)},tol:binary64(0)})),edges:[],loops:[],faces:[],shells:[],solids:[],coedges:[]};const database=await semioBrepSnapshotToSqliteDatabase(s),db=Database.deserialize(await exportSqliteDatabase(database));try{expect(db.query("SELECT count(*) AS n FROM semio_brep_vertex").get()).toEqual({n:a.collectionItems});expect(db.query("SELECT native_id FROM semio_brep_vertex WHERE ordinal=?").get(a.cancelAfter)).toEqual({native_id:a.cancelAfter.toString()});expect(db.query("SELECT count(*) AS n FROM semio_brep_vertex WHERE x_numeric_class='nan' AND x IS NULL").get()).toEqual({n:a.collectionItems/f.float64Bits.length*2});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);}finally{db.close();}expect(await semioBrepSnapshotFromSqliteDatabase(database)).toEqual(s);for(const phase of["projectSnapshot","reconstructSnapshot"]){const abort=new AbortController();let inside=false;const options={signal:abort.signal,onProgress:(p:{phase:string,completed:number})=>{if(p.phase===phase&&p.completed===a.cancelAfter){inside=true;abort.abort();}}};await expect(phase==="projectSnapshot"?semioBrepSnapshotToSqliteDatabase(s,options):semioBrepSnapshotFromSqliteDatabase(database,options)).rejects.toHaveProperty("kind","canceled");expect(inside).toBe(true);}await expect(semioBrepSnapshotToSqliteDatabase(s,{maxValueBytes:a.tinyBudgetBytes})).rejects.toThrow();await expect(semioBrepSnapshotToSqliteDatabase(s,{maxRows:a.collectionItems})).rejects.toThrow();});

import intermediateBrep from "../🧫️fixtures/🧩️intermediate/🔣️.json";

for(const neutral of intermediateBrep.cases)test("Semio BRep code-admitted "+neutral.name+" has full independently editable physical SQLite",async()=>{
 const{default:Ajv}=await import("ajv");expect(intermediateBrep["role"]).toEqual("codeAdmittedIntermediateOwner");
 const raw=structuredClone(neutral.snapshot),point=(p:{x:number,y:number,z:number})=>({x:binary64(p.x),y:binary64(p.y),z:binary64(p.z)});
 const snapshot:SemioBrepSnapshot={...raw,nextLabel:BigInt(raw.nextLabel),vertices:raw.vertices.map(v=>({...v,point:point(v.point),tol:binary64(v.tol)})),edges:raw.edges.map(e=>({...e,curve:{kind:"line",origin:point(e.curve.origin),direction:point(e.curve.direction)},tol:binary64(e.tol)})),faces:raw.faces.map(v=>({...v,surface:{kind:"plane",origin:point(v.surface.origin),normal:point(v.surface.normal)},tol:binary64(v.tol)})),coedges:raw.coedges.map(c=>({...c,pcurve:null,prange:[binary64(c.prange[0]!),binary64(c.prange[1]!)]}))};
 const db=Database.deserialize(await exportSqliteDatabase(await semioBrepSnapshotToSqliteDatabase(snapshot)));
 try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(neutral.query).all()).toEqual(neutral.expectedRows);expect(await semioBrepSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(snapshot);db.query("UPDATE semio_brep_edge SET start_vertex_native_id=?").run("independently edited");snapshot.edges[0]!.startVertex="independently edited";expect(await semioBrepSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(snapshot);console.log("[DEBUG] Semio BRep complete intermediate topology owner preserved: "+neutral.name);}finally{db.close();}
});

import completeSemanticContract from "../🧫️fixtures/🎛️semantic.json";
import completeSemanticSchema from "../🧫️fixtures/🧬️semantic.json";
import Ajv2020Complete from "ajv/dist/2020";
import{independentSqliteExtent as completeIndependentExtent}from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧪️tests/🔮️semantic-extent/🟦️.ts";
test("Semio Brep Native matched full and metadata empty independently preserve all complete cells",async()=>{
 expect(new Ajv2020Complete({strict:true}).compile(completeSemanticSchema)(completeSemanticContract)).toBe(true);
 for(const item of completeSemanticContract.cases){const source=structuredClone(item.sourceSnapshot)as unknown as SemioBrepSnapshot;const hydrate=(value:unknown):unknown=>Array.isArray(value)?value.map(hydrate):value!==null&&typeof value==="object"?("bits"in value?{bits:String((value as {bits:string}).bits).length===8?Number.parseInt(String((value as {bits:string}).bits),16):BigInt("0x"+String((value as {bits:string}).bits))}:Object.fromEntries(Object.entries(value).map(([key,item])=>[key,hydrate(item)]))):value;Object.assign(source,hydrate(source));source.nextLabel=BigInt(source.nextLabel);const database=await semioBrepSnapshotToSqliteDatabase(source),bytes=await exportSqliteDatabase(database);expect(completeIndependentExtent(bytes)).toEqual({rows:item.rows,valueBytes:item.valueBytes,schemaBytes:completeSemanticContract.schemaBytes,tableWidths:completeSemanticContract.tableWidths});const limits={maxRows:item.rows,maxValueBytes:item.valueBytes,maxSchemaBytes:completeSemanticContract.schemaBytes,maxTables:25,maxColumns:54};expect(await semioBrepSnapshotToSqliteDatabase(source,limits)).toEqual(database);expect(await semioBrepSnapshotFromSqliteDatabase(await importSqliteDatabase(bytes),limits)).toEqual(source);
 for(const short of[{...limits,maxRows:item.rows-1},{...limits,maxValueBytes:item.valueBytes-1},{...limits,maxSchemaBytes:limits.maxSchemaBytes-1},{...limits,maxTables:24},{...limits,maxColumns:53}]){await expect(semioBrepSnapshotToSqliteDatabase(source,short)).rejects.toThrow();await expect(semioBrepSnapshotFromSqliteDatabase(database,short)).rejects.toThrow();}
 }console.log("[DEBUG] Semio Brep independently measured Native matched full and empty roles through all5 copied limits");
});
